<?php
declare(strict_types=1);require __DIR__.'/includes/ui.php';$u=msw_require_user();$uid=(int)$u['id'];$cost=['common_metal'=>2500,'minor_metal'=>1600,'precious_metal'=>550,'fuel'=>2200];$active=msw_one("SELECT * FROM base_projects WHERE user_id=? AND project_key='strategic_deterrent' AND state IN('building','complete') ORDER BY id DESC LIMIT 1",'i',[$uid]);
if($active && $active['state']==='building' && strtotime((string)$active['finish_at'])<=time()){msw_stmt("UPDATE base_projects SET state='complete' WHERE id=? AND user_id=? AND state='building'",'ii',[(int)$active['id'],$uid]);$active=msw_one('SELECT * FROM base_projects WHERE id=?','i',[(int)$active['id']]);}
if(msw_is_post()){msw_verify_post();$action=(string)($_POST['action']??'');if($action==='start'){if($active)msw_flash('A strategic project is already active or awaiting claim.','warning');elseif(!msw_spend_resources($uid,$cost))msw_flash('Insufficient materials.','error');else{$seconds=(int)msw_config('strategic_project_seconds');$finish=date('Y-m-d H:i:s',time()+$seconds);msw_stmt("INSERT INTO base_projects(user_id,project_key,state,started_at,finish_at,payload_json) VALUES(?,'strategic_deterrent','building',NOW(),?,?)",'iss',[$uid,$finish,json_encode(['rating_bonus'=>5000])]);msw_console_event_for_user($uid,'STRATEGIC','START','Strategic deterrent production started.',['finish_at'=>$finish]);msw_flash('Strategic deterrent production started. Timer is persisted in MySQL.','success');}}elseif($action==='claim'&&$active&&$active['state']==='complete'){msw_stmt('UPDATE player_resources SET strategic_devices=strategic_devices+1 WHERE user_id=?','i',[$uid]);msw_stmt("UPDATE base_projects SET state='claimed' WHERE id=? AND user_id=?",'ii',[(int)$active['id'],$uid]);msw_console_event_for_user($uid,'STRATEGIC','CLAIM','Completed strategic deterrent claimed.',['project_id'=>(int)$active['id']]);msw_flash('Strategic deterrent added to base inventory.','success');}msw_redirect('strategic.php');}
$active=msw_one("SELECT * FROM base_projects WHERE user_id=? AND project_key='strategic_deterrent' AND state IN('building','complete') ORDER BY id DESC LIMIT 1",'i',[$uid]);msw_header('Strategic Systems','base.php');msw_alert(msw_flash());msw_resource_strip($uid);?><section class="hero"><div class="eyebrow">STRATEGIC SYSTEMS</div><h1>NUCLEAR <span>DETERRENCE</span></h1><p>A fictional late-game base superpower system implemented strictly as game economy, ranking and persistent-time state. Construction uses an absolute completion timestamp, so restarting Apache, PHP or the browser does not reset progress.</p></section><?php msw_panel('Nuclear Deterrent','PERSISTENT REAL-TIME PROJECT');if($active):?><p>Status: <span class="grade"><?=msw_e(strtoupper($active['state']))?></span></p><?php if($active['state']==='building'):?><div class="timer" data-countdown="<?=msw_e(date(DATE_ATOM,strtotime((string)$active['finish_at'])))?>">--:--:--</div><p>Completion: <?=msw_e($active['finish_at'])?></p><?php else:?><form method="post"><?=msw_csrf_field()?><button name="action" value="claim">Claim Completed Project</button></form><?php endif;?><?php else:?><p>Production cost:</p><table><tbody><?php foreach($cost as $k=>$v):?><tr><td><?=msw_e(ucwords(str_replace('_',' ',$k)))?></td><td><?=number_format($v)?></td></tr><?php endforeach;?></tbody></table><form method="post" style="margin-top:12px"><?=msw_csrf_field()?><button name="action" value="start">Begin Production</button></form><?php endif;msw_panel_end();msw_footer();?>
